CustomField.formula:
IF ( Solicitud_booking_enviada__c , IMAGE ( "/img/samples/flag_green.gif" , "Booking Listo" ) ,
IF ( ISBLANK ( Fecha_Minima_Embarque__c ) , IMAGE ( "/img/msg_icons/warning16.png" , "Sin ISW" ) & " Sin ISW" ,
IF ( Fecha_Minima_Embarque__c - TODAY() <= 0 , IMAGE ( "/img/msg_icons/error16.png" , "Violación ISW" ) & " Sin booking después de ISW" ,
IF ( Fecha_Minima_Embarque__c - TODAY() <= 45 , IMAGE ( "/img/samples/flag_red.gif" , "Booking Cerca" ) & " Faltan " & TEXT ( Fecha_Minima_Embarque__c - TODAY() ) & " días" ,
IMAGE ( "/img/samples/flag_yellow.gif" , "Booking Pendiente" )  & " Faltan " & TEXT ( Fecha_Minima_Embarque__c - TODAY() ) & " días"
)
)
)
)
